CREATE TABLE IF NOT EXISTS public.v23_demand_signals (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, ingredient_id uuid not null references public.ingredients(id) on delete cascade, location_id uuid references public.locations(id) on delete cascade, signal_date date not null, demand_quantity numeric(24,8) not null check(demand_quantity>=0), unit text not null, source text not null check(source in ('consumption','forecast','manual','sales')), confidence numeric(8,4) check(confidence>=0 and confidence<=1), created_at timestamptz not null default now(), unique(business_id,ingredient_id,location_id,signal_date,source));
CREATE TABLE IF NOT EXISTS public.v23_supplier_replenishment_runs (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, run_date date not null default current_date, status text not null default 'planned' check(status in ('planned','approved','executed','blocked','cancelled')), source_window_days integer not null check(source_window_days between 1 and 365), created_by uuid references auth.users(id), approved_by uuid references auth.users(id), created_at timestamptz not null default now(), approved_at timestamptz, executed_at timestamptz);
CREATE TABLE IF NOT EXISTS public.v23_supplier_replenishment_lines (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, run_id uuid not null references public.v23_supplier_replenishment_runs(id) on delete cascade, ingredient_id uuid not null references public.ingredients(id) on delete restrict, supplier_id uuid references public.suppliers(id) on delete restrict, location_id uuid references public.locations(id) on delete restrict, unit text not null, current_stock numeric(24,8) not null, projected_demand numeric(24,8) not null, reorder_point numeric(24,8) not null default 0, recommended_quantity numeric(24,8) not null check(recommended_quantity>=0), reason text not null, purchase_plan_id uuid references public.purchase_plans(id) on delete set null, purchase_order_id uuid references public.purchase_orders(id) on delete set null, created_at timestamptz not null default now(), unique(run_id,ingredient_id,supplier_id,location_id));
CREATE INDEX IF NOT EXISTS idx_v23_replenishment_lines_run ON public.v23_supplier_replenishment_lines(business_id,run_id);
CREATE TABLE IF NOT EXISTS public.v23_supplier_commitments (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, replenishment_line_id uuid not null references public.v23_supplier_replenishment_lines(id) on delete cascade, supplier_id uuid not null references public.suppliers(id) on delete restrict, committed_quantity numeric(24,8) not null check(committed_quantity>=0), unit text not null, expected_at timestamptz, supplier_reference text, status text not null default 'pending' check(status in ('pending','confirmed','partial','declined','fulfilled','cancelled')), created_at timestamptz not null default now(), confirmed_at timestamptz);
CREATE INDEX IF NOT EXISTS idx_v23_commitments_active ON public.v23_supplier_commitments(business_id,supplier_id,status,expected_at);
ALTER TABLE public.v23_demand_signals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v23_supplier_replenishment_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v23_supplier_replenishment_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.v23_supplier_commitments ENABLE ROW LEVEL SECURITY;
CREATE POLICY v23_demand_select ON public.v23_demand_signals FOR SELECT USING(is_member(business_id));
CREATE POLICY v23_run_select ON public.v23_supplier_replenishment_runs FOR SELECT USING(is_member(business_id));
CREATE POLICY v23_line_select ON public.v23_supplier_replenishment_lines FOR SELECT USING(is_member(business_id));
CREATE POLICY v23_commitment_select ON public.v23_supplier_commitments FOR SELECT USING(is_member(business_id));
REVOKE INSERT,UPDATE,DELETE ON public.v23_demand_signals FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v23_supplier_replenishment_runs FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v23_supplier_replenishment_lines FROM authenticated;
REVOKE INSERT,UPDATE,DELETE ON public.v23_supplier_commitments FROM authenticated;
CREATE OR REPLACE FUNCTION public.v23_generate_replenishment_run(p_business_id uuid,p_window_days integer default 14) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r_id uuid; BEGIN IF NOT has_role(p_business_id,ARRAY['owner','manager']::member_role[]) THEN RAISE EXCEPTION 'Manager authorization required'; END IF; IF p_window_days<1 OR p_window_days>365 THEN RAISE EXCEPTION 'Invalid demand window'; END IF; INSERT INTO public.v23_supplier_replenishment_runs(business_id,source_window_days,created_by) VALUES(p_business_id,p_window_days,auth.uid()) RETURNING id INTO r_id; INSERT INTO public.v23_supplier_replenishment_lines(business_id,run_id,ingredient_id,supplier_id,location_id,unit,current_stock,projected_demand,reorder_point,recommended_quantity,reason) SELECT p_business_id,r_id,v.ingredient_id,v.supplier_id,v.location_id,v.unit,v.current_stock,v.projected_demand,v.reorder_point,greatest(v.projected_demand+v.reorder_point-v.current_stock,0),case when v.current_stock<=v.reorder_point then 'Below reorder point' when v.projected_demand+v.reorder_point>v.current_stock then 'Projected demand exceeds available stock' else 'Within coverage' end FROM (SELECT i.id ingredient_id,(SELECT s.id FROM public.suppliers s WHERE s.business_id=p_business_id AND s.status='active' ORDER BY s.id LIMIT 1) supplier_id,l.id location_id,i.purchase_unit unit,coalesce((SELECT sum(im.quantity) FROM public.inventory_movements im WHERE im.business_id=p_business_id AND im.ingredient_id=i.id AND im.location_id=l.id),0) current_stock,coalesce((SELECT sum(ds.demand_quantity) FROM public.v23_demand_signals ds WHERE ds.business_id=p_business_id AND ds.ingredient_id=i.id AND ds.location_id=l.id AND ds.signal_date>=current_date AND ds.signal_date<current_date+p_window_days),0) projected_demand,coalesce(i.minimum_stock,0) reorder_point FROM public.ingredients i CROSS JOIN public.locations l WHERE i.business_id=p_business_id AND l.business_id=p_business_id) v WHERE v.current_stock<=v.reorder_point OR v.projected_demand+v.reorder_point>v.current_stock ON CONFLICT DO NOTHING; RETURN r_id; END $$;
CREATE OR REPLACE FUNCTION public.v23_approve_replenishment_run(p_run_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r public.v23_supplier_replenishment_runs; BEGIN SELECT * INTO r FROM public.v23_supplier_replenishment_runs WHERE id=p_run_id FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Replenishment run not found'; END IF; IF NOT has_role(r.business_id,ARRAY['owner','manager']::member_role[]) THEN RAISE EXCEPTION 'Manager authorization required'; END IF; IF r.status<>'planned' THEN RAISE EXCEPTION 'Run is not awaiting approval'; END IF; UPDATE public.v23_supplier_replenishment_runs SET status='approved',approved_by=auth.uid(),approved_at=now() WHERE id=p_run_id; END $$;
CREATE OR REPLACE FUNCTION public.v23_commit_supplier_quantity(p_line_id uuid,p_quantity numeric,p_expected_at timestamptz,p_supplier_reference text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE l public.v23_supplier_replenishment_lines; c_id uuid; BEGIN SELECT * INTO l FROM public.v23_supplier_replenishment_lines WHERE id=p_line_id FOR UPDATE; IF l.id IS NULL THEN RAISE EXCEPTION 'Replenishment line not found'; END IF; IF NOT has_role(l.business_id,ARRAY['owner','manager']::member_role[]) THEN RAISE EXCEPTION 'Manager authorization required'; END IF; IF l.supplier_id IS NULL THEN RAISE EXCEPTION 'No supplier is assigned to replenishment line'; END IF; IF p_quantity<0 OR p_quantity>l.recommended_quantity THEN RAISE EXCEPTION 'Invalid supplier commitment quantity'; END IF; INSERT INTO public.v23_supplier_commitments(business_id,replenishment_line_id,supplier_id,committed_quantity,unit,expected_at,supplier_reference,status,confirmed_at) VALUES(l.business_id,l.id,l.supplier_id,p_quantity,l.unit,p_expected_at,p_supplier_reference,case when p_quantity=l.recommended_quantity then 'confirmed' when p_quantity>0 then 'partial' else 'declined' end,now()) RETURNING id INTO c_id; RETURN c_id; END $$;
GRANT EXECUTE ON FUNCTION public.v23_generate_replenishment_run(uuid,integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.v23_approve_replenishment_run(uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.v23_commit_supplier_quantity(uuid,numeric,timestamptz,text) TO authenticated;
CREATE OR REPLACE VIEW public.view_v23_replenishment_control_tower AS SELECT r.business_id,r.id run_id,r.status,r.run_date,count(l.id) line_count,coalesce(sum(l.recommended_quantity),0) recommended_quantity,coalesce(sum(case when c.status in ('confirmed','partial') then c.committed_quantity else 0 end),0) committed_quantity,count(*) filter(where l.recommended_quantity>0 and coalesce(c.committed_quantity,0)<l.recommended_quantity) uncommitted_lines FROM public.v23_supplier_replenishment_runs r LEFT JOIN public.v23_supplier_replenishment_lines l ON l.run_id=r.id LEFT JOIN public.v23_supplier_commitments c ON c.replenishment_line_id=l.id GROUP BY r.business_id,r.id,r.status,r.run_date;